/* Quem vale consultar agora, e por onde.

   A origem do card diz o sistema E a conta. Antes disso o campo guardava
   "Loggi MB", que com duas contas de Manda Bem não identificava mais nada —
   a consulta iria para a conta errada e voltaria "não encontrado", que na
   tela parece problema do pacote e não da configuração. */
const todos = $input.first().json || {};
const agora = Date.now();
const DIAS_ATE_DESISTIR = 45;

const ORIGENS = {
  'Melhor Envio · Antonio Carlos': 'me_antonio',
  'Melhor Envio · Raphael':        'me_raphael',
  'Manda Bem · Daniel':            'mb_daniel',
  'Manda Bem · 4Vita':             'mb_4vita',
  'Base (Mercado Livre, Shopee, Magalu)': 'base'
};

/* O id que o painel do Manda Bem entende é numérico e já está dentro do
   próprio código de rastreio: "MB0000000328080" carrega o 328080. Deduzir
   aqui evita depender de alguém digitar certo. Não-numérico no campo é
   ignorado de propósito: id errado consulta o envio de outra pessoa, o que é
   pior do que não consultar. */
function idDoMandaBem(r) {
  const doCard = String(r.envioId || r.coletaId || '').trim();
  if (/^\d+$/.test(doCard)) return doCard;
  const doCodigo = String(r.codigo || '').replace(/\D/g, '').replace(/^0+/, '');
  return doCodigo || '';
}

const fila = [];
const fora = { semOrigem: 0, semId: 0, entregue: 0, velho: 0, esperando: 0 };

Object.keys(todos).forEach(chave => {
  const r = todos[chave];
  if (!r) return;

  if (r.status === 'Entregue') { fora.entregue++; return; }
  if (r.trackProximaConsulta && agora < r.trackProximaConsulta) { fora.esperando++; return; }

  /* Pacote parado há mais de 45 dias não volta a andar porque perguntamos de
     novo. Sai da fila e vira problema humano, não de robô. */
  const nasceu = Number(r.ordemManual || 0);
  if (nasceu && (agora - nasceu) > DIAS_ATE_DESISTIR * 864e5) { fora.velho++; return; }

  const via = ORIGENS[String(r.intermediador || '').trim()];
  if (!via) { fora.semOrigem++; return; }

  let id = '';
  if (via === 'base')            id = String(r.nped || '').replace(/\D/g, '');
  else if (via.indexOf('mb_')===0) id = idDoMandaBem(r);
  else                            id = String(r.envioId || '').trim();

  if (!id) { fora.semId++; return; }

  fila.push({ json: {
    chave, via, id,
    codigo: r.codigo || '',
    statusAtual: r.status || '',
    transp: r.transp || '',
    previsao: r.previsao || '',
    trackLog: Array.isArray(r.trackLog) ? r.trackLog : []
  }});
});

console.log(fila.length + ' na fila · fora: ' +
  Object.keys(fora).map(k => k + '=' + fora[k]).join(' '));

if (fora.semOrigem) {
  console.log(fora.semOrigem + ' card(s) sem "Onde consultar" definido — ' +
    'esses ficam sem rastreio automático até alguém escolher a conta no card.');
}

return fila;

/* A resposta do Melhor Envio vem chaveada pelo id do pedido, e o item que
   entrou aqui perdeu os campos do card. Recupera os dois lados antes do
   Padroniza. */
const card = $('Lotes de 10').item.json;
return [{ json: Object.assign({}, card, { respostaME: $json }) }];

/* Um pedido pode ter mais de um pacote (envio parcial). Todos entram na
   consulta de histórico: ignorar os demais mostraria o card como parado
   enquanto metade da compra já chegou. */
const card = $('Lotes de 10').item.json;
const r = $json || {};
if (r.status && r.status !== 'SUCCESS') {
  throw new Error('A Base recusou: ' + (r.error_message || r.error_code || ''));
}
const ids = (r.packages || []).map(p => Number(p.package_id)).filter(Boolean);
const cur = (r.packages || [])[0] || {};
return [{ json: Object.assign({}, card, {
  packageIds: ids,
  courierCode: cur.courier_code || '',
  courierNome: cur.courier_other_name || ''
}) }];

const card = $('Ids dos pacotes').item.json;
const r = $json || {};
if (r.status && r.status !== 'SUCCESS') {
  throw new Error('A Base recusou o histórico: ' + (r.error_message || r.error_code || ''));
}
return [{ json: Object.assign({}, card, { historico: r.packages_history || {} }) }];

/* O painel é Laravel: o POST de login só é aceito com o _token (CSRF) que a
   própria tela de login entrega, junto do cookie de sessão daquela visita.
   Por isso o login tem dois passos — abrir a tela, depois enviar. */
const r = $input.first().json;
const corpo = String(r.body || r.data || '');
const m = corpo.match(/name="csrf-token"\s+content="([^"]+)"/)
       || corpo.match(/name="_token"\s+value="([^"]+)"/);
if (!m) throw new Error('Não achei o _token na tela de login — o painel pode ter mudado');

const bruto = (r.headers || {})['set-cookie'] || [];
const cookie = (Array.isArray(bruto) ? bruto : [bruto])
  .map(c => String(c).split(';')[0]).join('; ');

return [{ json: { csrf: m[1], cookie } }];

/* Guarda o cookie da sessão já autenticada, para os nós do painel
   reaproveitarem. Sem captcha no login, isso se renova a cada rodada — ninguém
   precisa colar cookie à mão quando expirar. */
const r = $input.first().json;
const bruto = (r.headers || {})['set-cookie'] || [];
const novos = (Array.isArray(bruto) ? bruto : [bruto])
  .map(c => String(c).split(';')[0]);
const anterior = $('Token Daniel').first().json.cookie || '';

// O cookie da sessão logada substitui o da visita anônima quando repetido
const mapa = {};
(anterior.split('; ').concat(novos)).forEach(c => {
  const i = c.indexOf('=');
  if (i > 0) mapa[c.slice(0, i)] = c.slice(i + 1);
});
const cookie = Object.entries(mapa).map(([k, v]) => k + '=' + v).join('; ');

/* Login recusado tem que parar AQUI, alto. O Laravel responde 200 com a
   própria tela de login quando a senha está errada — nada explode, o cookie
   até existe, e a falha só reaparece três nós adiante como "401 não
   autenticado" ou, pior, como "detalhe vazio", que parece problema do envio.
   Login aceito redireciona (302 + Location). */
const status = Number(r.statusCode || r.status || 0);
const cabecalhos = r.headers || {};
const local = cabecalhos.location || cabecalhos.Location || '';
const corpo = String(r.body || '');
const telaDeLogin = /css\/login\/|name="password"|id="password"|esqueci\s*minha\s*senha/i.test(corpo);

if (!local && status < 300 && telaDeLogin) {
  throw new Error('Login do Manda Bem recusado: o painel devolveu a tela de login de novo. ' +
                  'Confira a senha no campo "password" do nó "Login Manda Bem" — no arquivo do ' +
                  'repositório ela vai como PREENCHER_A_SENHA_AQUI, porque o repositório é público.');
}
return [{ json: { cookie } }];

