/* O HTML do detalhe traz o botão da lupa com o endereço do rastreio pronto.
   Ler daqui vale mais que qualquer tabela de slugs: funciona para
   transportadora que ainda nem existe no cadastro.

   Três cuidados aprendidos na marra:
   · o data-path costuma vir RELATIVO ("coleta/status_jadlog_objeto/328080").
     Mandar isso para o nó HTTP dá ERR_INVALID_URL, que na tela vira um erro
     sem sentido para quem só queria saber onde está a encomenda;
   · nem todo envio tem o botão — sem objeto postado, ele não existe. Isso não
     é falha do fluxo, é estado do pacote, e precisa dizer isso;
   · o HTML vem com barras escapadas (\/) por causa do JSON. */
const BASE = 'https://painel.mandabem.com.br/';
const html = $json.html || $json.data || '';

let achado = '';
const padroes = [
  /class="[^"]*btn-get-status-objeto-envio[^"]*"[^>]*data-path="([^"]+)"/i,
  /data-path="([^"]*status[^"]*objeto[^"]*)"/i,
  /data-path="([^"]*(?:rastre|track)[^"]*)"/i,
  /(?:href|data-url)="([^"]*status[^"]*objeto[^"]*)"/i
];
for (const re of padroes) {
  const m = String(html).match(re);
  if (m && m[1]) { achado = m[1]; break; }
}

let url = achado.replace(/\\\//g, '/').trim();
if (url && !/^https?:\/\//i.test(url)) url = BASE + url.replace(/^\/+/, '');

// Sem link, o motivo vai junto: é ele que o card vai mostrar
const motivo = url ? ''
  : (String(html).trim()
      ? 'O Manda Bem não mostrou botão de rastreio neste envio — normalmente é objeto ainda não postado'
      : 'O Manda Bem devolveu o detalhe vazio para este envio');

return { json: { ...$json, trackUrl: url, trackUrlMotivo: motivo } };

/* As movimentações do Manda Bem chegam como HTML de tabela. Aqui viram uma
   lista simples, para o Padroniza tratar todas as origens do mesmo jeito.

   O painel não devolve carimbo em segundos: a data vem escrita na linha, no
   formato brasileiro. Converter aqui evita que o Padroniza precise conhecer
   o formato de cada origem. */
const html = String($json.body || $json.data || $json.html || '');
const mov = [];

/* Cada linha da tabela costuma vir como
     <td>21/08/2026 14:32</td><td>Objeto em trânsito ...</td>
   e a ordem das colunas varia entre transportadoras, então a data é
   procurada em qualquer célula e o texto é o resto da linha. */
const linhas = html.split(/<tr[^>]*>/i).slice(1);
linhas.forEach(bruto => {
  const celulas = bruto.split(/<\/?td[^>]*>/i)
    .map(c => c.replace(/<[^>]*>/g, ' ').replace(/&nbsp;/g, ' ').replace(/\s+/g, ' ').trim())
    .filter(Boolean);
  if (!celulas.length) return;

  let ts = 0, texto = [];
  celulas.forEach(c => {
    const m = c.match(/(\d{2})\/(\d{2})\/(\d{4})(?:\s+(\d{2}):(\d{2}))?/);
    if (m && !ts) {
      ts = Math.floor(new Date(+m[3], +m[2] - 1, +m[1], +(m[4] || 0), +(m[5] || 0)).getTime() / 1000);
      const resto = c.replace(m[0], '').trim();
      if (resto) texto.push(resto);
    } else {
      texto.push(c);
    }
  });

  const t = texto.join(' — ').trim();
  if (t) mov.push({ ts: ts, texto: t });
});

/* Sem nenhuma linha reconhecida, é melhor dizer isso do que devolver lista
   vazia em silêncio: lista vazia parece "pacote sem movimento", e não é. */
if (!mov.length && html.length > 200) {
  throw new Error('O painel respondeu mas não reconheci nenhuma movimentação — o HTML pode ter mudado');
}

return [{ json: Object.assign({}, $json, { movimentacoes: mov }) }];

