return [{ json: Object.assign({}, $json, { movimentacoes: mov }) }];

/* Tudo que veio das cinco origens vira o mesmo formato aqui.

   Duas saídas por card:
   · status — uma palavra em português, que é o que a tela mostra;
   · trackLog — a linha do tempo, com o texto ORIGINAL da transportadora.

   Guardar os dois não é redundância: o status precisa ser comparável entre
   Mercado Envios, Shopee Xpress e Correios, e o log precisa ser fiel ao que
   a transportadora disse — traduzir o log apagaria a informação de origem
   justamente no lugar onde ela é a prova. */

const LIMITE_LOG = 40;
const TZ = 'America/Sao_Paulo';

function carimbo(ts) {
  const d = ts ? new Date(Number(ts) * 1000) : new Date();
  return new Intl.DateTimeFormat('pt-BR', {
    timeZone: TZ, day: '2-digit', month: '2-digit', year: 'numeric',
    hour: '2-digit', minute: '2-digit'
  }).format(d);
}

/* O número do tracking_status da Base é o mesmo entre as transportadoras —
   confirmado em 21/08/2026 comparando Mercado Envios, Shopee Xpress e
   Magalog. O texto muda ("DELIVERED", "delivered", "entregue"); o número não.
   Por isso a tradução usa o número, e o texto vai inteiro para o log. */
const STATUS_BASE = {
  '0': 'Aguardando postagem',
  '1': 'Aguardando postagem',
  '2': 'Em trânsito',
  '3': 'Em trânsito',
  '4': 'Saiu para entrega',
  '5': 'Entregue',
  '6': 'Devolvido',
  '7': 'Extraviado',
  '8': 'Cancelado'
};

/* Melhor Envio e Manda Bem falam por texto, não por código. */
const STATUS_TEXTO = [
  [/entregue|delivered/i,                       'Entregue'],
  [/saiu para entrega|out_for_delivery/i,       'Saiu para entrega'],
  [/devolv|returned/i,                          'Devolvido'],
  [/extravi|lost/i,                             'Extraviado'],
  [/cancel/i,                                   'Cancelado'],
  [/tr[âa]nsito|transit|encaminhad|coletad|picked_up|shipped|posta/i, 'Em trânsito'],
  [/aguardando|pending|ready_to_ship|created/i, 'Aguardando postagem']
];

function traduzirTexto(txt) {
  const t = String(txt || '');
  for (let i = 0; i < STATUS_TEXTO.length; i++) {
    if (STATUS_TEXTO[i][0].test(t)) return STATUS_TEXTO[i][1];
  }
  return '';
}

/* A Base reconfirma o mesmo estado a cada leitura: o histórico da Shopee
   veio com PICKED_UP quatro vezes, em dias diferentes. Sem colapsar, o card
   mostraria quatro linhas dizendo a mesma coisa. Fica a PRIMEIRA de cada
   sequência — que é quando o pacote realmente entrou naquele estado. */
function semRepetidos(linhas) {
  const saida = [];
  let anterior = null;
  for (let i = 0; i < linhas.length; i++) {
    if (linhas[i].status !== anterior) saida.push(linhas[i]);
    anterior = linhas[i].status;
  }
  return saida;
}

const via = $json.via;
let linhas = [];   // {ts, status, em}
let erro = '';

try {
  if (via === 'base') {
    const hist = $json.historico || {};
    const pacotes = Object.keys(hist);
    pacotes.forEach(pid => {
      (hist[pid] || []).forEach(ev => {
        linhas.push({
          ts: Number(ev.tracking_status_date || 0),
          status: String(ev.courier_status_code || ''),
          num: String(ev.tracking_status || '')
        });
      });
    });
  } else if (via === 'me_antonio' || via === 'me_raphael') {
    /* A resposta do Melhor Envio vem chaveada pelo id do pedido. */
    const resp = $json.respostaME || {};
    const primeiro = resp[Object.keys(resp)[0]] || {};
    (primeiro.tracking || primeiro.events || []).forEach(ev => {
      linhas.push({
        ts: ev.date ? Math.floor(new Date(ev.date).getTime() / 1000) : 0,
        status: String(ev.status || ev.description || ev.title || '')
      });
    });
    if (!linhas.length && primeiro.status) {
      linhas.push({ ts: 0, status: String(primeiro.status) });
    }
  } else {
    /* Manda Bem: as movimentações já chegam normalizadas do nó anterior. */
    (($json.movimentacoes) || []).forEach(ev => {
      linhas.push({ ts: ev.ts || 0, status: String(ev.texto || '') });
    });
  }
} catch (e) {
  erro = String(e && e.message ? e.message : e);
}

linhas = linhas.filter(l => l.status).sort((a, b) => a.ts - b.ts);
linhas = semRepetidos(linhas);

const ultima = linhas.length ? linhas[linhas.length - 1] : null;
const statusNovo = ultima
  ? (via === 'base'
      ? (STATUS_BASE[ultima.num] || traduzirTexto(ultima.status) || 'Em trânsito')
      : (traduzirTexto(ultima.status) || 'Em trânsito'))
  : '';

/* O log é reconstruído inteiro a cada rodada, e não acrescentado: a fonte da
   verdade é a transportadora, não o que gravamos antes. Assim uma correção
   dela chega ao card em vez de ficar enterrada sob a nossa cópia antiga. */
const logNovo = linhas.slice(-LIMITE_LOG).reverse().map(l => ({
  em: carimbo(l.ts),
  status: l.status,
  fonte: via
}));

const logAntigo = Array.isArray($json.trackLog) ? $json.trackLog : [];
const mudouStatus = statusNovo && statusNovo !== $json.statusAtual;
const mudouLog = JSON.stringify(logNovo) !== JSON.stringify(logAntigo);

const patch = {
  trackVerificadoEm: carimbo(),
  trackLog: erro
    ? [{ em: carimbo(), erro: erro, fonte: via }].concat(logAntigo).slice(0, LIMITE_LOG)
    : logNovo,
  _by: 'n8n'
};
if (statusNovo) patch.status = statusNovo;
if (statusNovo === 'Entregue' && $json.statusAtual !== 'Entregue') {
  patch.entregueEm = carimbo();
}

return [{ json: {
  chave: $json.chave,
  mudou: !!(erro || mudouStatus || mudouLog),
  patch: patch
}}];

/* Chegou a data prevista: quem cadastrou o rastreio precisa conferir a baixa
   dentro da Base.

   A tarefa nasce UMA vez por rastreio — a marca trackTarefaCriada, gravada no
   próprio card, é o que impede a mesma cobrança de voltar a cada rodada. Sem
   ela, um rastreio parado geraria uma tarefa por minuto.

   Pacote já entregue não gera nada: a conferência existe para o caso em que
   a data chegou e o pacote NÃO andou. */
const todos = $input.first().json || {};
const hoje = new Date();
hoje.setHours(0, 0, 0, 0);

function comoData(txt) {
  const s = String(txt || '').trim();
  let m = s.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (m) return new Date(+m[1], +m[2] - 1, +m[3]);
  m = s.match(/^(\d{2})\/(\d{2})\/(\d{2})$/);
  if (m) return new Date(2000 + +m[3], +m[2] - 1, +m[1]);
  m = s.match(/^(\d{2})\/(\d{2})\/(\d{4})$/);
  if (m) return new Date(+m[3], +m[2] - 1, +m[1]);
  return null;
}

const saida = [];
Object.keys(todos).forEach(chave => {
  const r = todos[chave];
  if (!r) return;
  if (r.trackTarefaCriada) return;
  if (r.status === 'Entregue') return;

  const prev = comoData(r.previsao);
  if (!prev) return;
  prev.setHours(0, 0, 0, 0);
  if (prev > hoje) return;          // ainda não chegou o dia

  const quem = r.criadoPorKey || '';
  if (!quem) {
    console.log('Rastreio ' + chave + ' venceu a previsão mas não tem criadoPorKey — ' +
                'sem isso não há a quem atribuir. Card antigo, cadastrado antes desse campo existir.');
    return;
  }

  const descricao = [
    'Rastreio ' + (r.codigo || chave) + (r.transp ? ' (' + r.transp + ')' : ''),
    'Previsão de entrega era ' + r.previsao + ' e o pacote ainda não consta como entregue.',
    'Situação atual: ' + (r.status || '—') + '.',
    'Conferir na Base se a baixa foi dada e atualizar o card.'
  ].join('\n');

  saida.push({ json: {
    chave: chave,
    tarefa: {
      titulo: 'Conferir entrega — ' + (r.nped ? 'pedido ' + r.nped : (r.codigo || chave)),
      descricao: descricao,
      responsaveis: [quem],
      responsavel: quem,
      prioridade: 'alta',
      vencimento: new Date().toISOString().slice(0, 10),
      origemRastreioId: chave,
      criadoPor: 'Rastreador Live',
      criadoPorKey: 'sistema'
    }
  }});
});

console.log(saida.length + ' tarefa(s) de conferência a criar');
return saida;
